def _locale(value: str | None) -> Locale | None:
    language = (value or "").strip().lower().replace("_", "-").split("-", 1)[0]
    if language in CATALOGS:
        return language
    return None


def resolve_locale(explicit: str | None = None, accept_language: str | None = None) -> Locale:
    """Resolve explicit, environment, browser language, then Spanish."""
    if locale := _locale(explicit):
        return locale
    if locale := _locale(os.environ.get("HOME_OPS_LANG")):
        return locale
    for item in (accept_language or "").split(","):
        if locale := _locale(item.split(";", 1)[0]):
            return locale
    return "es"


def t(key: str, locale: Locale | str = "es", **vars: object) -> str:
    """Translate a key; Spanish fallback and missing variables remain literal."""
    text = CATALOGS.get(_locale(locale) or "es", CATALOGS["es"]).get(key, CATALOGS["es"].get(key, key))
    try:
        return text.format(**vars)
    except (IndexError, KeyError, ValueError):
        return text

